#include "module.hpp"
#include <cctype>
#include <cstring>

namespace {
	uint16_t u16(std::vector<uint8_t> const& d, size_t o)
	{
		if (o + 2 > d.size()) {
			throw blitz::recompiler::not_blitz("truncated file");
		}
		return uint16_t(d[o] | (d[o + 1] << 8));
	}

	uint32_t u32(std::vector<uint8_t> const& d, size_t o)
	{
		if (o + 4 > d.size()) {
			throw blitz::recompiler::not_blitz("truncated file");
		}
		return uint32_t(d[o]) | (uint32_t(d[o + 1]) << 8) | (uint32_t(d[o + 2]) << 16) | (uint32_t(d[o + 3]) << 24);
	}

	constexpr uint32_t RT_RCDATA = 10;
	constexpr uint32_t PROGRAM   = 1111;
} // namespace

namespace blitz::recompiler {

	symbol_kind module::kind(std::string const& name)
	{
		if (name.size() < 2 || name[0] != '_') {
			return symbol_kind::other;
		}
		if (name[1] == '_') {
			if (name == "__MAIN" || name == "__DATA" || name == "__LIBS") {
				return symbol_kind::section;
			}
			return name.compare(0, 4, "__bb") == 0 ? symbol_kind::support : symbol_kind::other;
		}
		if (name[1] >= '0' && name[1] <= '9') {
			return symbol_kind::label;
		}
		switch (name[1]) {
		case 'f':
			return symbol_kind::function;
		case 'v':
			return symbol_kind::global;
		case 'a':
			return symbol_kind::array;
		case 't':
			return symbol_kind::type;
		}
		return symbol_kind::other;
	}

	module parse_module(uint8_t const* data, size_t size)
	{
		auto fail = [](char const* why) { throw not_blitz(std::string("the program is not a Blitz module (") + why + ")"); };
		if (size < 4) {
			fail("too small");
		}
		auto rd32 = [&](size_t o) {
			if (o + 4 > size) {
				fail("truncated");
			}
			return uint32_t(data[o]) | (uint32_t(data[o + 1]) << 8) | (uint32_t(data[o + 2]) << 16) | (uint32_t(data[o + 3]) << 24);
		};
		module   m;
		uint32_t code_size = rd32(0);
		if (code_size > size - 4) {
			fail("code is larger than the resource");
		}
		m.code.assign(data + 4, data + 4 + code_size);
		size_t p = 4 + size_t(code_size);
		for (auto* table : { &m.labels, &m.relative, &m.absolute }) {
			uint32_t n = rd32(p);
			p += 4;
			if (n > (size - p) / 6) {
				fail("symbol table is larger than the resource");
			}
			table->reserve(n);
			for (uint32_t i = 0; i < n; i++) {
				auto end = static_cast<uint8_t const*>(std::memchr(data + p, 0, size - p));
				if (!end) {
					fail("unterminated name");
				}
				size_t   len = size_t(end - (data + p));
				symbol   s{ std::string(reinterpret_cast<char const*>(data + p), len), 0 };
				p += len + 1;
				s.offset = rd32(p);
				p += 4;
				if (s.offset > code_size) {
					fail("symbol outside of the code");
				}
				table->push_back(std::move(s));
			}
		}
		if (p != size) {
			fail("data after the tables");
		}
		for (auto const& s : m.labels) {
			m.defined[s.name] = s.offset;
		}
		return m;
	}

	bool parse_declaration(std::string const& t, declaration& out)
	{
		size_t p = 0;
		char   ret = 'v';
		if (p < t.size() && (t[p] == '%' || t[p] == '#' || t[p] == '$')) {
			ret = (t[p] == '%') ? 'i' : (t[p] == '#' ? 'f' : 's');
			p++;
		}
		auto word = [&]() {
			size_t b = p;
			if (p < t.size() && (std::isalpha(uint8_t(t[p])) || t[p] == '_')) {
				p++;
				while (p < t.size() && (std::isalnum(uint8_t(t[p])) || t[p] == '_')) {
					p++;
				}
			}
			return t.substr(b, p - b);
		};
		std::string name = word();
		if (name.empty()) {
			return false;
		}
		std::string params;
		while (p < t.size()) {
			char c = t[p];
			if (c != '%' && c != '#' && c != '$') {
				return false;
			}
			p++;
			if (word().empty()) {
				return false;
			}
			params += (c == '%') ? 'i' : (c == '#' ? 'f' : 's');
			if (p < t.size() && t[p] == '=') {
				p++;
				if (p < t.size() && t[p] == '"') {
					size_t e = t.find('"', p + 1);
					if (e == std::string::npos) {
						return false;
					}
					p = e + 1;
				} else {
					size_t b = p;
					while (p < t.size() && (std::isdigit(uint8_t(t[p])) || t[p] == '-' || t[p] == '.' || t[p] == 'e' || t[p] == 'E' || t[p] == '+')) {
						p++;
					}
					if (p == b) {
						return false;
					}
				}
			}
		}
		out.name   = name;
		out.ret    = ret;
		out.params = params;
		return true;
	}

	module load_module(std::vector<uint8_t> const& d)
	{
		if (d.size() < 0x40 || d[0] != 'M' || d[1] != 'Z') {
			throw not_blitz("not a PE file");
		}
		size_t pe = u32(d, 0x3C);
		if (u32(d, pe) != 0x00004550) {
			throw not_blitz("not a PE file");
		}
		size_t sections = u16(d, pe + 6);
		size_t opt      = pe + 24;
		if (u16(d, opt) != 0x10B) {
			throw not_blitz("not a 32-bit PE file (Blitz programs are x86)");
		}
		size_t res_rva = u32(d, opt + 96 + 2 * 8);
		struct section {
			uint32_t va, size, raw;
		};
		std::vector<section> secs;
		for (size_t i = 0; i < sections; i++) {
			size_t s = opt + u16(d, pe + 20) + i * 40;
			secs.push_back({ u32(d, s + 12), std::max(u32(d, s + 8), u32(d, s + 16)), u32(d, s + 20) });
		}
		auto offset = [&](size_t rva) {
			for (auto const& s : secs) {
				if (rva >= s.va && rva < size_t(s.va) + s.size) {
					return size_t(rva - s.va + s.raw);
				}
			}
			throw not_blitz("bad resource address");
		};
		if (!res_rva) {
			throw not_blitz("no resources");
		}
		size_t base = offset(res_rva);
		auto   entries = [&](size_t dir) {
			std::vector<std::pair<uint32_t, uint32_t>> list;
			size_t n = size_t(u16(d, dir + 12)) + u16(d, dir + 14);
			for (size_t i = 0; i < n; i++) {
				list.emplace_back(u32(d, dir + 16 + i * 8), u32(d, dir + 20 + i * 8));
			}
			return list;
		};
		for (auto [tname, tptr] : entries(base)) {
			if (tname != RT_RCDATA || !(tptr & 0x80000000)) {
				continue;
			}
			for (auto [iname, iptr] : entries(base + (tptr & 0x7FFFFFFF))) {
				if (iname != PROGRAM || !(iptr & 0x80000000)) {
					continue;
				}
				for (auto [lname, lptr] : entries(base + (iptr & 0x7FFFFFFF))) {
					size_t rva  = u32(d, base + lptr);
					size_t size = u32(d, base + lptr + 4);
					size_t off  = offset(rva);
					if (off + size > d.size()) {
						throw not_blitz("truncated file");
					}
					module m = parse_module(d.data() + off, size);
					// The runtime of the original lists its commands as strings, which tell how many arguments each one has.
					for (size_t at = 0; at < d.size();) {
						if (at >= off && at < off + size) {
							at = off + size;
							continue;
						}
						size_t e = at;
						while (e < d.size() && d[e] >= 32 && d[e] < 127 && e - at < 256) {
							e++;
						}
						if (e < d.size() && d[e] == 0 && e - at >= 2 && (at == 0 || d[at - 1] == 0)) {
							declaration decl;
							std::string text(reinterpret_cast<char const*>(d.data()) + at, e - at);
							if (parse_declaration(text, decl)) {
								std::string key = decl.name;
								for (auto& c : key) {
									c = char(std::tolower(uint8_t(c)));
								}
								// A name without parameters and result is also an ordinary word: take it only if nothing better is known.
								auto it = m.declarations.find(key);
								bool plain = decl.ret == 'v' && decl.params.empty();
								if (it == m.declarations.end() || (it->second.ret == 'v' && it->second.params.empty() && !plain)) {
									m.declarations[key] = decl;
								}
							}
						}
						at = e + 1;
					}
					return m;
				}
			}
		}
		throw not_blitz("no program resource (RCDATA 1111)");
	}
} // namespace blitz::recompiler
